// SPDX-License-Identifier: MIT
pragma solidity 0.8.38;

import {V4Types, IUniV4Quoter, IInfinityQuoter} from "./v4/V4Types.sol";
import {V4NetworkConfig} from "./v4/V4NetworkConfig.sol";

/// @notice Stores a single executor's approved, hook-free direct pools and constructs typed router inputs.
/// @dev The helper holds no operating balances or approvals. Only its creating executor may configure it.
contract V4QuoteHelper {
    error InvalidV4Pool();
    error V4OnlyController();

    uint256 private constant MAX_SWAP_AMOUNT = uint128(type(int128).max);
    uint256 private constant MAX_QUOTE_GAS = 1_000_000;

    address public immutable controller;
    address private immutable _wrapped;
    address[12] private _dependencies;
    V4Types.Pool[] private _pools;
    bytes32 private _lockId;
    address private _input;
    address private _output;

    constructor(address wrapped) {
        if (wrapped != V4NetworkConfig.wrappedNative() || wrapped.code.length == 0) revert InvalidV4Pool();
        address[12] memory deps = V4NetworkConfig.dependencies();
        for (uint256 i; i < deps.length; ++i) {
            if (deps[i] != address(0) && deps[i].code.length == 0) revert InvalidV4Pool();
        }
        _wrapped = wrapped;
        _dependencies = deps;
        controller = msg.sender;
    }

    modifier onlyController() {
        if (msg.sender != controller) revert V4OnlyController();
        _;
    }

    function getV4Config() external view returns (address[12] memory) {
        return _dependencies;
    }

    function getV4Policy() external view returns (V4Types.Pool[] memory, bytes32) {
        return (_pools, _lockId);
    }

    function hasV4() external view returns (bool) {
        return _pools.length != 0;
    }

    function v4Locked() external view returns (bool) {
        return _lockId != bytes32(0);
    }

    function clearV4() external onlyController {
        delete _pools;
        delete _lockId;
        delete _input;
        delete _output;
    }

    function configureV4(
        V4Types.Pool[] calldata pools,
        bytes32 lockId,
        uint8 venue,
        address input,
        address output
    ) external onlyController {
        if (pools.length == 0 || pools.length > 8 || input == output || input == address(0) || output == address(0)) {
            revert InvalidV4Pool();
        }

        delete _pools;
        bool foundLock = lockId == bytes32(0);
        for (uint256 i; i < pools.length; ++i) {
            V4Types.Pool calldata pool = pools[i];
            _validatePool(pool, venue, input, output);
            for (uint256 j; j < i; ++j) {
                if (pools[j].poolId == pool.poolId) revert InvalidV4Pool();
            }
            if (pool.poolId == lockId) foundLock = true;
            _pools.push(pool);
        }
        if (!foundLock) revert InvalidV4Pool();
        _lockId = lockId;
        _input = input;
        _output = output;
    }

    function quote(address tokenIn, uint256 amount)
        external
        returns (V4Types.Route memory best, V4Types.Route[] memory routes)
    {
        if (tokenIn != _input || tokenIn == address(0)) revert InvalidV4Pool();
        routes = new V4Types.Route[](_pools.length);
        for (uint256 i; i < _pools.length; ++i) {
            V4Types.Pool memory pool = _pools[i];
            address manager = _manager(pool.kind);
            uint256 amountOut = _quoteCandidate(pool, manager, tokenIn, amount);
            V4Types.Route memory candidate =
                V4Types.Route(pool.kind, pool.fee, address(0), amountOut, 0, pool.poolId, manager, uint8(i));
            routes[i] = candidate;
            if (amountOut > best.amountOut) best = candidate;
        }
    }

    function quoteV4(address input, uint256 amount)
        external
        returns (
            uint8[] memory kinds,
            bytes32[] memory ids,
            address[] memory managers,
            uint256[] memory outputs,
            uint24[] memory fees
        )
    {
        if (input != _input || input == address(0)) revert InvalidV4Pool();
        uint256 count = _pools.length;
        kinds = new uint8[](count);
        ids = new bytes32[](count);
        managers = new address[](count);
        outputs = new uint256[](count);
        fees = new uint24[](count);
        for (uint256 i; i < count; ++i) {
            V4Types.Pool memory pool = _pools[i];
            address manager = _manager(pool.kind);
            kinds[i] = pool.kind;
            ids[i] = pool.poolId;
            managers[i] = manager;
            outputs[i] = _quoteCandidate(pool, manager, input, amount);
            fees[i] = pool.fee;
        }
    }

    function reverseV4(uint8 index, bytes32 id, address input, uint256 amount) external returns (uint256) {
        if (input != _output) revert InvalidV4Pool();
        V4Types.Pool memory pool = _candidate(index, id);
        return _quoteCandidate(pool, _manager(pool.kind), input, amount);
    }

    function encodeV4(uint8 index, bytes32 id, address input, address output, uint256 amount, uint256 minimum)
        external
        view
        returns (
            address router,
            address permit2,
            bool nativeInput,
            bool nativeOutput,
            bytes memory commands,
            bytes[] memory inputs
        )
    {
        if (amount == 0 || amount > MAX_SWAP_AMOUNT || minimum > MAX_SWAP_AMOUNT) revert InvalidV4Pool();
        if (!(input == _input && output == _output) && !(input == _output && output == _input)) {
            revert InvalidV4Pool();
        }
        V4Types.Pool memory pool = _candidate(index, id);
        bool zeroForOne = _asset(pool.currency0) == input;
        address currencyIn = zeroForOne ? pool.currency0 : pool.currency1;
        address currencyOut = zeroForOne ? pool.currency1 : pool.currency0;
        nativeInput = currencyIn == address(0);
        nativeOutput = currencyOut == address(0);

        bytes[] memory params = new bytes[](3);
        if (pool.kind == V4Types.UNISWAP) {
            router = _dependencies[1];
            permit2 = _dependencies[4];
            // Universal Router 2.1.2 includes a per-hop field. The explicit amount floor governs this single hop.
            params[0] = abi.encode(
                V4Types.UniSwap(V4Types.uniKey(pool), zeroForOne, uint128(amount), uint128(minimum), 0, "")
            );
        } else {
            router = _dependencies[8];
            permit2 = _dependencies[11];
            params[0] = abi.encode(
                V4Types.InfinitySwap(
                    V4Types.infinityKey(pool, _manager(pool.kind)), zeroForOne, uint128(amount), uint128(minimum), ""
                )
            );
        }
        params[1] = abi.encode(currencyIn, amount);
        params[2] = abi.encode(currencyOut, minimum);

        uint8 swapAction = pool.kind == V4Types.INFINITY_BIN ? 0x1c : 0x06;
        bytes memory actions = abi.encodePacked(swapAction, uint8(0x0c), uint8(0x0f));
        commands = hex"10";
        inputs = new bytes[](1);
        inputs[0] = abi.encode(actions, params);
    }

    function _validatePool(V4Types.Pool calldata pool, uint8 venue, address input, address output) private view {
        if (pool.hooks != address(0) || pool.currency0 >= pool.currency1 || pool.fee >= 1_000_000) {
            revert InvalidV4Pool();
        }
        address asset0 = _asset(pool.currency0);
        address asset1 = _asset(pool.currency1);
        if (!(asset0 == input && asset1 == output) && !(asset0 == output && asset1 == input)) {
            revert InvalidV4Pool();
        }

        address manager = _manager(pool.kind);
        if (manager == address(0)) revert InvalidV4Pool();
        bytes32 id;
        if (pool.kind == V4Types.UNISWAP) {
            if (venue != 0 || pool.parameters != bytes32(0) || pool.tickSpacing <= 0 || pool.tickSpacing > 32767) {
                revert InvalidV4Pool();
            }
            id = keccak256(abi.encode(V4Types.uniKey(pool)));
        } else {
            if (venue != 2) revert InvalidV4Pool();
            uint256 bits = uint256(pool.parameters);
            uint256 step = bits >> 16;
            if (uint16(bits) != 0 || step == 0) revert InvalidV4Pool();
            if (pool.kind == V4Types.INFINITY_CL) {
                if (step > 32767 || pool.tickSpacing <= 0 || uint256(uint24(pool.tickSpacing)) != step) {
                    revert InvalidV4Pool();
                }
            } else if (step > 100 || pool.tickSpacing != 0 || pool.fee > 100_000) {
                revert InvalidV4Pool();
            }
            id = keccak256(abi.encode(V4Types.infinityKey(pool, manager)));
        }
        if (id != pool.poolId) revert InvalidV4Pool();
    }

    function _candidate(uint8 index, bytes32 id) private view returns (V4Types.Pool memory pool) {
        if (index >= _pools.length || (_lockId != bytes32(0) && id != _lockId)) revert InvalidV4Pool();
        pool = _pools[index];
        if (pool.poolId != id) revert InvalidV4Pool();
    }

    function _quoteCandidate(V4Types.Pool memory pool, address manager, address input, uint256 amount)
        private
        returns (uint256 out)
    {
        if (amount == 0 || amount > MAX_SWAP_AMOUNT || (_lockId != bytes32(0) && _lockId != pool.poolId)) {
            return 0;
        }
        bool zeroForOne = _asset(pool.currency0) == input;
        if (pool.kind == V4Types.UNISWAP) {
            V4Types.UniQuote memory params = V4Types.UniQuote(V4Types.uniKey(pool), zeroForOne, uint128(amount), "");
            try IUniV4Quoter(_dependencies[2]).quoteExactInputSingle{gas: MAX_QUOTE_GAS}(params)
                returns (uint256 received, uint256)
            {
                out = received;
            } catch {}
        } else {
            address quoter = _dependencies[pool.kind == V4Types.INFINITY_CL ? 9 : 10];
            V4Types.InfinityQuote memory params =
                V4Types.InfinityQuote(V4Types.infinityKey(pool, manager), zeroForOne, uint128(amount), "");
            try IInfinityQuoter(quoter).quoteExactInputSingle{gas: MAX_QUOTE_GAS}(params)
                returns (uint256 received, uint256)
            {
                out = received;
            } catch {}
        }
        if (out > MAX_SWAP_AMOUNT) return 0;
    }

    function _asset(address currency) private view returns (address) {
        return currency == address(0) ? _wrapped : currency;
    }

    function _manager(uint8 kind) private view returns (address) {
        if (kind == V4Types.UNISWAP) return _dependencies[0];
        if (kind == V4Types.INFINITY_CL) return _dependencies[6];
        if (kind == V4Types.INFINITY_BIN) return _dependencies[7];
        revert InvalidV4Pool();
    }
}

contracts/V4SwapExecutor.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.38;

import {TradeCore} from "./common/TradeCore.sol";
import {IWETH, TokenOps} from "./common/TokenOps.sol";
import {V4QuoteHelper} from "./V4QuoteHelper.sol";
import {V4NetworkConfig} from "./v4/V4NetworkConfig.sol";
import {V4Types, IV4UniversalRouter, IV4Permit2} from "./v4/V4Types.sol";

/// @notice Owner-funded, single-round Uniswap V4 and PancakeSwap Infinity executor.
contract V4SwapExecutor is TradeCore {
    error V4SwapFailed();

    event DexPolicyUpdated(uint8 dex);

    uint256 private constant MAX_SWAP_AMOUNT = uint128(type(int128).max);

    struct Settings {
        address tokenIn;
        address tokenOut;
        address recipient;
        uint8 priceMode;
        uint256 minBuyAmount;
        bool checkBurn;
        uint16 maxBurnBps;
        bool testSell;
        uint16 testSellBps;
    }

    V4QuoteHelper public immutable quoteHelper;
    uint8 public dex;
    Settings private _settings;

    constructor(address initialOwner) TradeCore(initialOwner, V4NetworkConfig.wrappedNative()) {
        quoteHelper = new V4QuoteHelper(wrappedNative);
    }

    function getSettings() external view returns (Settings memory) {
        return _settings;
    }

    function getDexPolicy() external view returns (uint8 venue, uint32[] memory) {
        return (dex, new uint32[](0));
    }

    function getV4Policy() external view returns (V4Types.Pool[] memory, bytes32) {
        return quoteHelper.getV4Policy();
    }

    function setSettingsAndV4(
        Settings calldata next,
        uint16 sellLossBps,
        uint8 venue,
        V4Types.Pool[] calldata pools,
        bytes32 lockId
    ) external onlyOwner nonReentrant {
        _checkRecipient(next.recipient);
        if (
            next.tokenIn == next.tokenOut || next.tokenIn.code.length == 0 || next.tokenOut.code.length == 0
                || next.maxBurnBps > BPS || next.testSellBps > BPS || next.minBuyAmount > MAX_SWAP_AMOUNT
                || ((next.checkBurn || next.testSell) && next.testSellBps == 0)
        ) {
            revert InvalidSettings();
        }
        if (next.priceMode > 1 || (next.priceMode == 1) != (next.minBuyAmount != 0)) {
            revert InvalidPriceProtection();
        }

        quoteHelper.configureV4(pools, lockId, venue, next.tokenIn, next.tokenOut);
        _settings = next;
        dex = venue;
        _afterSettings(sellLossBps);
        emit SettingsUpdated(next.tokenIn, next.tokenOut, next.recipient);
        emit DexPolicyUpdated(venue);
    }

    function quoteBest(uint256 amountIn)
        external
        returns (V4Types.Route memory best, V4Types.Route[] memory candidates)
    {
        if (_settings.tokenIn == address(0)) revert NotConfigured();
        return quoteHelper.quote(_settings.tokenIn, amountIn);
    }

    /// @notice Simulates the current route, then always rolls back the trial swaps and allowance changes.
    function simulateTaxSaved(uint256 amountIn, uint16 probeBps) external onlyOwner nonReentrant {
        try this.runTaxSimulationSaved(amountIn, probeBps) returns (TaxExecutionResult memory result) {
            _report(result);
        } catch (bytes memory reason) {
            revert TaxSimulationFailed(reason);
        }
    }

    /// @dev The external boundary separates adapter reverts from the executor's own TaxReport.
    function runTaxSimulationSaved(uint256 amountIn, uint16 probeBps)
        external
        returns (TaxExecutionResult memory)
    {
        if (msg.sender != address(this)) revert TaxSimulationOnlySelf();
        if (probeBps == 0 || probeBps > BPS) revert InvalidSettings();
        if (_settings.tokenIn == address(0)) revert NotConfigured();
        if (amountIn == 0 || TokenOps.balanceOf(_settings.tokenIn, address(this)) < amountIn) {
            revert InsufficientInput();
        }
        V4Types.Route memory best = _bestRoute(amountIn);
        return _settleTrade(best, amountIn, 0, block.timestamp, probeBps, false);
    }

    function _settingsInput() internal view override returns (address) {
        return _settings.tokenIn;
    }

    function _settingsMinimum() internal view override returns (uint256) {
        return _settings.minBuyAmount;
    }

    function _executeTrade(
        uint256 amountIn,
        uint256 requestedMinimum,
        uint256 deadline
    ) internal override returns (uint256 bought, uint256 received, uint256 testInputRecovered) {
        V4Types.Route memory route = _bestRoute(amountIn);
        uint256 minimum = _executionMinimum(requestedMinimum);
        bool checkBurn = _settings.checkBurn;
        uint16 probeBps = (_settings.testSell || checkBurn) ? _settings.testSellBps : 0;
        TaxExecutionResult memory result = _settleTrade(route, amountIn, minimum, deadline, probeBps, checkBurn);
        emit Bought(
            result.kind,
            result.pool,
            result.fee,
            result.amountIn,
            result.expectedBuy,
            result.bought,
            result.received,
            result.recovered
        );
        return (result.bought, result.received, result.recovered);
    }

    function _bestRoute(uint256 amountIn) private returns (V4Types.Route memory route) {
        (route,) = quoteHelper.quote(_settings.tokenIn, amountIn);
        if (route.amountOut == 0) revert NoEligiblePool();
    }

    function _settleTrade(
        V4Types.Route memory route,
        uint256 amountIn,
        uint256 minimum,
        uint256 deadline,
        uint16 probeBps,
        bool enforceLossLimits
    ) private returns (TaxExecutionResult memory result) {
        Settings memory settings = _settings;
        result.amountIn = amountIn;
        result.expectedBuy = route.amountOut;
        result.kind = route.kind;
        result.pool = route.pool;
        result.fee = route.fee;
        if (minimum > result.expectedBuy) revert MinimumNotMet(result.expectedBuy, minimum);
        result.bought = _swap(route, settings.tokenIn, settings.tokenOut, amountIn, minimum == 0 ? 1 : minimum, deadline);

        if (probeBps != 0) {
            result.probeAmount = _lossFloor(result.bought, BPS - probeBps);
            if (result.probeAmount == 0) revert SellProbeFailed();
            result.expectedSell =
                quoteHelper.reverseV4(route.candidateIndex, route.poolId, settings.tokenOut, result.probeAmount);
            if (result.expectedSell == 0) revert SellProbeFailed();
            result.recovered =
                _swap(route, settings.tokenOut, settings.tokenIn, result.probeAmount, 1, deadline);
            if (enforceLossLimits && result.recovered < _requiredAfterLoss(result.expectedSell, maxSellLossBps)) {
                revert SellLossLimitExceeded(result.expectedSell, result.recovered);
            }
        }

        result.forwarded = result.bought - result.probeAmount;
        // These two factors are bounded by the signed pool amount width.
        result.expectedRecipient = (result.expectedBuy * result.forwarded) / result.bought;
        if (result.forwarded != 0) {
            result.received = _forward(settings.tokenOut, settings.recipient, result.forwarded);
            if (minimum != 0) {
                uint256 recipientMinimum = (minimum * result.forwarded) / result.bought;
                if (recipientMinimum == 0) recipientMinimum = 1;
                if (result.received < recipientMinimum) revert MinimumNotMet(result.received, recipientMinimum);
            }
        }
        if (enforceLossLimits) {
            if (result.bought < _requiredAfterLoss(result.expectedBuy, settings.maxBurnBps)) {
                revert BurnLimitExceeded(result.expectedBuy, result.bought);
            }
            if (result.received < _requiredAfterLoss(result.expectedRecipient, settings.maxBurnBps)) {
                revert BurnLimitExceeded(result.expectedRecipient, result.received);
            }
        }
    }

    function _swap(
        V4Types.Route memory route,
        address input,
        address output,
        uint256 amount,
        uint256 minimum,
        uint256 deadline
    ) private returns (uint256 received) {
        (address router, address permit2, bool nativeInput, bool nativeOutput, bytes memory commands, bytes[] memory args)
        = quoteHelper.encodeV4(route.candidateIndex, route.poolId, input, output, amount, minimum);
        uint256 inputBefore = TokenOps.balanceOf(input, address(this));
        uint256 outputBefore = TokenOps.balanceOf(output, address(this));
        if (amount > inputBefore) revert InsufficientInput();

        uint256 nativeBefore = address(this).balance;
        uint256 routerNativeBefore;
        if (nativeInput) {
            routerNativeBefore = router.balance;
            IWETH(wrappedNative).withdraw(amount);
            if (address(this).balance != nativeBefore + amount) revert UnexpectedBalance();
        } else {
            TokenOps.forceApprove(input, permit2, amount);
            IV4Permit2(permit2).approve(input, router, uint160(amount), uint48(block.timestamp));
        }

        try IV4UniversalRouter(router).execute{value: nativeInput ? amount : 0}(commands, args, deadline) {}
        catch {
            revert V4SwapFailed();
        }

        if (nativeInput) {
            // Full-input settlement cannot leave value with either the executor or the router.
            if (address(this).balance != nativeBefore || router.balance != routerNativeBefore) {
                revert UnexpectedBalance();
            }
        } else {
            IV4Permit2(permit2).approve(input, router, 0, 0);
            TokenOps.forceApprove(input, permit2, 0);
            if (nativeOutput) {
                if (address(this).balance <= nativeBefore) revert V4SwapFailed();
                IWETH(wrappedNative).deposit{value: address(this).balance - nativeBefore}();
            }
            if (address(this).balance != nativeBefore) revert UnexpectedBalance();
        }

        uint256 inputAfter = TokenOps.balanceOf(input, address(this));
        uint256 outputAfter = TokenOps.balanceOf(output, address(this));
        if (inputAfter != inputBefore - amount || outputAfter < outputBefore) revert UnexpectedBalance();
        received = outputAfter - outputBefore;
        if (received < minimum) revert MinimumNotMet(received, minimum);
        if (received > MAX_SWAP_AMOUNT) revert UnexpectedBalance();
    }

    function _forward(address token, address recipient, uint256 amount) private returns (uint256 received) {
        uint256 senderBefore = TokenOps.balanceOf(token, address(this));
        uint256 recipientBefore = TokenOps.balanceOf(token, recipient);
        TokenOps.transfer(token, recipient, amount);
        uint256 recipientAfter = TokenOps.balanceOf(token, recipient);
        if (
            senderBefore < amount || TokenOps.balanceOf(token, address(this)) != senderBefore - amount
                || recipientAfter < recipientBefore
        ) {
            revert UnexpectedBalance();
        }
        return recipientAfter - recipientBefore;
    }
}

contracts/common/TokenOps.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.38;

interface IWETH {
    function deposit() external payable;
    function withdraw(uint256 amount) external;
}

library TokenOps {
    error TokenOperationFailed(address token);

    function balanceOf(address token, address account) internal view returns (uint256) {
        (bool ok, bytes memory result) =
            token.staticcall(abi.encodeWithSelector(bytes4(0x70a08231), account));
        if (!ok || result.length != 32) revert TokenOperationFailed(token);
        return abi.decode(result, (uint256));
    }

    function transfer(address token, address to, uint256 amount) internal {
        if (!_call(token, abi.encodeWithSelector(bytes4(0xa9059cbb), to, amount))) {
            revert TokenOperationFailed(token);
        }
    }

    function forceApprove(address token, address spender, uint256 amount) internal {
        if (_call(token, abi.encodeWithSelector(bytes4(0x095ea7b3), spender, amount))) return;
        if (!_call(token, abi.encodeWithSelector(bytes4(0x095ea7b3), spender, 0))) {
            revert TokenOperationFailed(token);
        }
        if (!_call(token, abi.encodeWithSelector(bytes4(0x095ea7b3), spender, amount))) {
            revert TokenOperationFailed(token);
        }
    }

    function _call(address token, bytes memory data) private returns (bool) {
        (bool ok, bytes memory result) = token.call(data);
        if (!ok) return false;
        if (result.length == 0) return token.code.length != 0;
        return result.length == 32 && abi.decode(result, (uint256)) == 1;
    }
}

contracts/common/TradeCore.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.38;

import {IWETH, TokenOps} from "./TokenOps.sol";

abstract contract TradeCore {
    error AlreadyExecuted();
    error BurnLimitExceeded(uint256 expected, uint256 actual);
    error Expired();
    error InsufficientInput();
    error InvalidConfiguration();
    error InvalidPriceProtection();
    error InvalidSettings();
    error InvalidTriggerPolicy();
    error InvalidTriggerWallets();
    error MinimumNotMet(uint256 actual, uint256 minimum);
    error NativeTransferFailed();
    error NoEligiblePool();
    error NotConfigured();
    error NotOwner();
    error NotTriggerWallet();
    error Reentrancy();
    error SellLossLimitExceeded(uint256 expected, uint256 actual);
    error SellProbeFailed();
    error StaleTriggerEpoch();
    error TaxSimulationFailed(bytes reason);
    error TaxSimulationOnlySelf();
    error TriggerNotArmed();
    error TriggerTooEarly();
    error UnexpectedBalance();

    error TaxReport(
        uint256 amountIn,
        uint256 expectedBuy,
        uint256 bought,
        uint256 probeAmount,
        uint256 expectedSell,
        uint256 recovered,
        uint256 forwarded,
        uint256 expectedRecipient,
        uint256 received,
        uint8 kind,
        address pool,
        uint24 fee
    );

    event Bought(
        uint8 indexed kind,
        address indexed pool,
        uint24 fee,
        uint256 amountIn,
        uint256 quotedOut,
        uint256 bought,
        uint256 received,
        uint256 testInputRecovered
    );
    event NativeDeposited(uint256 amount);
    event SettingsUpdated(address indexed tokenIn, address indexed tokenOut, address recipient);
    event TaxLimitUpdated(uint16 maxSellLossBps);
    event TriggerArmed(uint256 indexed epoch, uint256 amountIn, uint16 slippageBps, uint64 notBefore, uint64 expiresAt);
    event TriggerDisarmed(uint256 indexed epoch);
    event TriggerExecuted(address indexed wallet, uint256 indexed epoch);
    event TriggerWalletsUpdated(address[] wallets, bool allowed);
    event Withdrawn(address indexed token, address indexed to, uint256 amount);

    struct TriggerPolicy {
        uint256 amountIn;
        uint16 slippageBps;
        uint64 notBefore;
        uint64 expiresAt;
    }

    struct TaxExecutionResult {
        uint256 amountIn;
        uint256 expectedBuy;
        uint256 bought;
        uint256 probeAmount;
        uint256 expectedSell;
        uint256 recovered;
        uint256 forwarded;
        uint256 expectedRecipient;
        uint256 received;
        uint8 kind;
        address pool;
        uint24 fee;
    }

    uint16 internal constant BPS = 10_000;

    address public immutable owner;
    address public immutable wrappedNative;
    uint256 public immutable networkChainId;

    uint16 public maxSellLossBps = 1_000;
    bool public executed;
    bool public triggerArmed;
    uint256 public triggerEpoch;
    mapping(address => bool) public isTriggerWallet;

    TriggerPolicy private _triggerPolicy;
    bool private _entered;

    constructor(address initialOwner, address wrapped) {
        if (initialOwner == address(0) || wrapped.code.length == 0) revert InvalidConfiguration();
        owner = initialOwner;
        wrappedNative = wrapped;
        networkChainId = block.chainid;
    }

    modifier onlyOwner() {
        if (msg.sender != owner) revert NotOwner();
        _;
    }

    modifier nonReentrant() {
        if (_entered) revert Reentrancy();
        _entered = true;
        _;
        _entered = false;
    }

    receive() external payable {}

    function depositNative() external payable nonReentrant {
        if (msg.value == 0) revert InsufficientInput();
        uint256 beforeDeposit = TokenOps.balanceOf(wrappedNative, address(this));
        IWETH(wrappedNative).deposit{value: msg.value}();
        if (TokenOps.balanceOf(wrappedNative, address(this)) != beforeDeposit + msg.value) {
            revert UnexpectedBalance();
        }
        emit NativeDeposited(msg.value);
    }

    function withdrawNative(address to, uint256 amount) external onlyOwner nonReentrant {
        _checkRecipient(to);
        _invalidateTrigger();
        uint256 nativeBalance = address(this).balance;
        if (amount == 0) amount = nativeBalance + TokenOps.balanceOf(wrappedNative, address(this));
        if (amount == 0) revert InsufficientInput();
        if (amount > nativeBalance) IWETH(wrappedNative).withdraw(amount - nativeBalance);
        (bool ok,) = payable(to).call{value: amount}("");
        if (!ok) revert NativeTransferFailed();
        emit Withdrawn(address(0), to, amount);
    }

    function withdrawToken(address token, address to, uint256 amount) external onlyOwner nonReentrant {
        _checkRecipient(to);
        _invalidateTrigger();
        // An explicit amount remains recoverable for tokens with a broken balanceOf.
        if (amount == 0) amount = TokenOps.balanceOf(token, address(this));
        if (amount == 0) revert InsufficientInput();
        TokenOps.transfer(token, to, amount);
        emit Withdrawn(token, to, amount);
    }

    function setTriggerWallets(address[] calldata wallets, bool allowed) external onlyOwner nonReentrant {
        if (wallets.length == 0 || wallets.length > 500) revert InvalidTriggerWallets();
        for (uint256 i; i < wallets.length; ++i) {
            if (wallets[i] == address(0) || wallets[i] == address(this)) revert InvalidTriggerWallets();
            isTriggerWallet[wallets[i]] = allowed;
        }
        _invalidateTrigger();
        emit TriggerWalletsUpdated(wallets, allowed);
    }

    function armTrigger(uint256 amountIn, uint16 slippageBps, uint64 notBefore, uint64 expiresAt)
        external
        onlyOwner
        nonReentrant
    {
        if (_settingsInput() == address(0)) revert NotConfigured();
        if (executed) revert AlreadyExecuted();
        // Keep the existing ABI's fixed-price mode marker. The owner sets the
        // absolute recipient floor in settings before arming a specific amount.
        if (amountIn == 0 || _settingsMinimum() == 0 || slippageBps != BPS
            || expiresAt <= block.timestamp || notBefore >= expiresAt) {
            revert InvalidTriggerPolicy();
        }
        ++triggerEpoch;
        _triggerPolicy = TriggerPolicy(amountIn, slippageBps, notBefore, expiresAt);
        triggerArmed = true;
        emit TriggerArmed(triggerEpoch, amountIn, slippageBps, notBefore, expiresAt);
    }

    function disarmTrigger() external onlyOwner nonReentrant {
        _invalidateTrigger();
    }

    function getTriggerPolicy() external view returns (TriggerPolicy memory) {
        return _triggerPolicy;
    }

    function buy(uint256 amountIn, uint256 minOut, uint256 deadline, uint256 expectedEpoch)
        external
        onlyOwner
        nonReentrant
        returns (uint256 bought, uint256 received, uint256 testInputRecovered)
    {
        _checkRound(expectedEpoch);
        if (block.timestamp > deadline) revert Expired();
        _beginTrade(amountIn);
        return _executeTrade(amountIn, minOut, deadline);
    }

    function trigger(uint256 expectedEpoch)
        external
        nonReentrant
        returns (uint256 bought, uint256 received, uint256 testInputRecovered)
    {
        if (!isTriggerWallet[msg.sender]) revert NotTriggerWallet();
        _checkRound(expectedEpoch);
        if (!triggerArmed) revert TriggerNotArmed();
        TriggerPolicy memory policy = _triggerPolicy;
        if (block.timestamp < policy.notBefore) revert TriggerTooEarly();
        if (block.timestamp > policy.expiresAt) revert Expired();
        uint256 minimumReceived = _settingsMinimum();
        _beginTrade(policy.amountIn);
        (bought, received, testInputRecovered) = _executeTrade(policy.amountIn, 0, policy.expiresAt);
        if (received < minimumReceived) revert MinimumNotMet(received, minimumReceived);
        emit TriggerExecuted(msg.sender, expectedEpoch);
    }

    function _afterSettings(uint16 sellLossBps) internal {
        if (sellLossBps > BPS) revert InvalidSettings();
        maxSellLossBps = sellLossBps;
        executed = false;
        _invalidateTrigger();
        emit TaxLimitUpdated(sellLossBps);
    }

    function _invalidateTrigger() internal {
        ++triggerEpoch;
        triggerArmed = false;
        delete _triggerPolicy;
        emit TriggerDisarmed(triggerEpoch);
    }

    function _executionMinimum(uint256 requestedMinimum) internal view returns (uint256) {
        uint256 fixedMinimum = _settingsMinimum();
        if (fixedMinimum != 0) {
            if (requestedMinimum != 0) revert InvalidPriceProtection();
            return fixedMinimum;
        }
        return requestedMinimum == 0 ? 1 : requestedMinimum;
    }

    function _lossFloor(uint256 expected, uint16 lossBps) internal pure returns (uint256) {
        uint256 kept = BPS - lossBps;
        return (expected / BPS) * kept + ((expected % BPS) * kept) / BPS;
    }

    function _requiredAfterLoss(uint256 expected, uint16 maximumLossBps) internal pure returns (uint256) {
        // Round the allowed loss down so even small trades cannot exceed the cap.
        return expected - _lossFloor(expected, BPS - maximumLossBps);
    }

    function _checkRecipient(address to) internal view {
        if (to == address(0) || to == address(this)) revert InvalidSettings();
    }

    function _report(TaxExecutionResult memory r) internal pure {
        revert TaxReport(
            r.amountIn,
            r.expectedBuy,
            r.bought,
            r.probeAmount,
            r.expectedSell,
            r.recovered,
            r.forwarded,
            r.expectedRecipient,
            r.received,
            r.kind,
            r.pool,
            r.fee
        );
    }

    function _checkRound(uint256 expectedEpoch) private view {
        if (expectedEpoch != triggerEpoch) revert StaleTriggerEpoch();
        if (executed) revert AlreadyExecuted();
        if (_settingsInput() == address(0)) revert NotConfigured();
    }

    function _beginTrade(uint256 amountIn) private {
        if (amountIn == 0 || TokenOps.balanceOf(_settingsInput(), address(this)) < amountIn) {
            revert InsufficientInput();
        }
        executed = true;
        triggerArmed = false;
    }

    function _settingsInput() internal view virtual returns (address);
    function _settingsMinimum() internal view virtual returns (uint256);
    function _executeTrade(uint256 amountIn, uint256 requestedMinimum, uint256 deadline)
        internal
        virtual
        returns (uint256 bought, uint256 received, uint256 testInputRecovered);
}

